const upsertBonusAccrual = `-- name: UpsertBonusAccrual :one
INSERT INTO bonus_accruals (
    organization_id, brand_id, user_id, period, rule_id, achievement_pct, amount, currency
)
VALUES (
    $1, $2, $3, $4,
    $5, $6, $7, $8
)
ON CONFLICT (user_id, rule_id, period) WHERE status <> 'cancelled' DO UPDATE
SET achievement_pct = EXCLUDED.achievement_pct,
    amount = EXCLUDED.amount,
    currency = EXCLUDED.currency
WHERE bonus_accruals.status = 'calculated'
RETURNING id, uuid, organization_id, brand_id, user_id, period, rule_id, achievement_pct, amount, currency, status, staff_payment_id, approved_by_user_id, approved_at, cancelled_at, created_at, updated_at
`

